//! Parse helpers the generated SMILES parser calls (`lit` / `tok` / `num`).
//!
//! Trimmed from xenosmarts-syntax `runtime.rs` — SMARTS QueryMol types stay
//! upstream. See [`super`].

use winnow::error::{ContextError, ErrMode, ParserError};
use winnow::prelude::*;
use winnow::stream::Stateful;
use winnow::token::{literal, take};

pub type PR<T> = Result<T, ErrMode<ContextError>>;

pub fn lit<'i, S: std::fmt::Debug>(i: &mut Stateful<&'i str, S>, s: &'static str) -> PR<()> {
    literal(s).void().parse_next(i)
}

/// Terminal via a generated byte matcher (see xenosmarts regex2rust.py).
pub fn tok<'i, S: std::fmt::Debug>(
    i: &mut Stateful<&'i str, S>,
    m: fn(&[u8]) -> Option<usize>,
) -> PR<&'i str> {
    match m(i.input.as_bytes()) {
        Some(n) if n > 0 => take(n).parse_next(i),
        _ => Err(ErrMode::from_input(i)),
    }
}

/// Test helper: a compiled matcher must agree with its source regex.
#[cfg(test)]
pub fn check_matcher(m: fn(&[u8]) -> Option<usize>, re: &str) {
    let re = regex::Regex::new(re).unwrap();
    let alphabet = b"0123456789+-#@?%{}^*&;,!:$()[]HhCcNnOoSsBbPpFIKlrRxXvDdZzkTAL";
    let mut seed = 0x9e3779b97f4a7c15u64;
    for _ in 0..200_000 {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        let len = (seed % 7) as usize;
        let s: Vec<u8> = (0..len)
            .map(|k| alphabet[((seed >> (8 * k)) % alphabet.len() as u64) as usize])
            .collect();
        let s = std::str::from_utf8(&s).unwrap();
        let want = re.find(s).map(|x| x.end());
        assert_eq!(m(s.as_bytes()), want, "{re} on {s:?}");
    }
}

pub fn num(s: &str) -> u32 {
    s.parse().expect("digits")
}
